mapper.select:
SELECT SUBSTRING(C_Date, 1, 6) as cDate, L_UID as lUtd, C_Name as cName, count(*) AS daycnt
  FROM tEnter
 WHERE L_Result = '0'
   AND SUBSTRING(C_Date, 1, 6) = #{searchDay}

   AND C_Name = #{eName}


    AND L_UID = #{eId}


    AND C_Office= = #{eGroup}

 GROUP BY SUBSTRING(C_Date, 1, 6), lutd, cName"
